import csv
import json
from difflib import ndiff

import pandas as pd


def task_func(file_path1, file_path2, delimiter=",", quotechar='"'):
    """Compare two CSV files and return a DataFrame difference report."""
    try:
        with open(file_path1, "r", newline="", encoding="utf-8") as file1:
            rows1 = [tuple(row) for row in csv.reader(
                file1, delimiter=delimiter, quotechar=quotechar
            )]
        with open(file_path2, "r", newline="", encoding="utf-8") as file2:
            rows2 = [tuple(row) for row in csv.reader(
                file2, delimiter=delimiter, quotechar=quotechar
            )]
    except FileNotFoundError:
        raise
    except OSError as exc:
        raise Exception(f"Unable to read CSV file: {exc}") from exc

    if not rows1 or not rows2:
        raise ValueError("Neither CSV file may be empty.")

    encoded1 = [json.dumps(row, ensure_ascii=False) for row in rows1]
    encoded2 = [json.dumps(row, ensure_ascii=False) for row in rows2]

    report = []
    for difference in ndiff(encoded1, encoded2):
        status = difference[0]
        if status not in (" ", "-", "+"):
            continue
        report.append(
            {
                "Line Number": len(report) + 1,
                "Status": status,
                "Content": tuple(json.loads(difference[2:])),
            }
        )

    return pd.DataFrame(report, columns=["Line Number", "Status", "Content"])
