import os
import re
from pathlib import Path


def task_func(dir_path: str, predicates: list) -> dict:
    valid_predicates = {"is_file", "is_dir", "has_special_chars", "has_numbers"}

    if not os.path.isdir(dir_path):
        raise FileNotFoundError(f"Directory not found: {dir_path}")

    selected = []
    for predicate in predicates:
        if isinstance(predicate, str) and predicate in valid_predicates and predicate not in selected:
            selected.append(predicate)

    if not selected:
        raise ValueError("No valid predicates provided.")

    result = {}
    for item in Path(dir_path).iterdir():
        name_without_extension = item.stem
        checks = {}

        for predicate in selected:
            if predicate == "is_file":
                checks[predicate] = item.is_file()
            elif predicate == "is_dir":
                checks[predicate] = item.is_dir()
            elif predicate == "has_special_chars":
                checks[predicate] = bool(
                    re.search(r"[^A-Za-z0-9_]", name_without_extension)
                )
            elif predicate == "has_numbers":
                checks[predicate] = bool(re.search(r"\d", item.name))

        result[item.name] = checks

    return result
